### 📝 간단한 풀이 과정

#### 338. Counting Bits

```javascript
/**
 * 17m26s 소요
 *
 * 시간복잡도 : O(n log n)
 *
 * O(n)으로 풀 수 있는거 같은데 잘 모르겠습니다.
 *
 * 1. 0부터 n까지의 수를 이진수로 변환한다.
 * 2. 0의 개수를 세고 배열에 저장한다.
 * 3. 배열을 반환한다.
 */
var countBits = function (n) {
  const result = [];

  // 0부터 n까지 반복 (O(n))
  for (let i = 0; i <= n; i++) {
    // 이진수로 변환 후 0의 개수를 세어 배열에 저장 (O(log n))
    result.push(i.toString(2).replace(/0/g, "").length);
  }

  return result;
};

```

#### 70.Climbing Stairs

```javascript
/**
 * 19m54s 소요
 *
 * 시간복잡도: O(n)
 *
 * 찾아보고 나서 풀 수 있었습니다.
 * dp(동적 프로그래밍)를 사용해서 풀 수 있는 문제입니다.
 *
 * 1. dp 배열을 생성하고 0으로 초기화합니다.
 * 2. dp[0]과 dp[1]을 1로 초기화합니다.
 * 3. 2부터 n까지 반복하면서 dp[i] = dp[i - 1] + dp[i - 2]를 수행합니다.
 * 4. dp[n]을 반환합니다.
 */
var climbStairs = function (n) {
  // dp 배열을 생성하고 0으로 초기화
  const dp = Array(n + 1).fill(0);

  dp[0] = 1;
  dp[1] = 1;

  // 2부터 n까지 반복 (O(n))
  for (let i = 2; i <= n; i++) {
    dp[i] = dp[i - 1] + dp[i - 2];
  }

  return dp[n];
};

```

#### 21. Merge two Sorted Lists

```javascript
/**
 * 28m11s 소요
 *
 * 시간복잡도: O(n)
 *
 * 어떻게 풀어야할지 모르겠어서 찾아봐서 풀었습니다.
 * 노드 어렵네요.
 *
 * 1. 두 리스트를 비교하면서 작은 값을 새로운 리스트에 추가합니다.
 * 2. 작은 값을 추가한 리스트의 다음 값을 작은 값이 아닌 리스트로 변경합니다.
 * 3. 1, 2를 반복합니다.
 * 4. 작은 값이 없는 리스트를 추가합니다.
 * 5. 새로운 리스트를 반환합니다.
 */
var mergeTwoLists = function (list1, list2) {
  let head = new ListNode();
  let current = head;

  // 두 리스트를 비교하면서 작은 값을 새로운 리스트에 추가 (O(n))
  while (list1 && list2) {
    if (list1.val < list2.val) {
      current.next = list1;
      list1 = list1.next;
    } else {
      current.next = list2;
      list2 = list2.next;
    }

    current = current.next;
  }

  current.next = list1 || list2;

  return head.next;
};

```

#### 48. Rotate Image

```javascript
/**
 * 31m11s 소요
 *
 * 시간 복잡도 O(n^2)
 *
 * 어려워서 찾아봤습니다. 풀이를 보니까 쉬운 문제인데 생각을 못했습니다.
 *
 * 1. 행과 열을 바꿉니다. (i, j) -> (j, i)
 * 2. 열을 뒤집습니다.
 * 3. 행렬을 반환합니다.
 */
var rotate = function (matrix) {
  const n = matrix.length;

  // 행과 열을 바꿉니다. (i, j) -> (j, i) (O(n^2))
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) {
      [matrix[i][j], matrix[j][i]] = [matrix[j][i], matrix[i][j]];
    }
  }

  // 열을 뒤집습니다. (O(n^2))
  for (let i = 0; i < n; i++) {
    matrix[i].reverse();
  }

  return matrix;
};

